// FlowBox — Gtk.FlowBox
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles flowbox with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { SelectionMode } from "@/lib/enums"

export interface FlowBoxProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.FlowBox */
  acceptUnpairedRelease?: boolean

  /** gboolean, from Gtk.FlowBox */
  activateOnSingleClick?: boolean

  /** guint, from Gtk.FlowBox */
  columnSpacing?: number

  /** gboolean, from Gtk.FlowBox */
  homogeneous?: boolean

  /** guint, from Gtk.FlowBox */
  maxChildrenPerLine?: number

  /** guint, from Gtk.FlowBox */
  minChildrenPerLine?: number

  /** guint, from Gtk.FlowBox */
  rowSpacing?: number

  /** SelectionMode, from Gtk.FlowBox */
  selectionMode?: SelectionMode
}

export function FlowBox({ className, children }: FlowBoxProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
